export { colors } from './colour';
export { fonts, FONT_REGULAR, FONT_MEDIUM, FONT_SERIF } from './fonts';
export { textStyles, fontSizes, lineHeights, letterSpacings, fontWeights } from './typography';
export { breakpoints, grid } from './gridSystem';
export { spacing, borderWidths, focusRingOffsets } from './spacing';
export { iconSizes, actionSizes } from './sizes';
export { motion } from './motion';
export { zimmTokens } from './zimmTokens';

// Spacing scale — source of truth: Figma node 2081:52901 (Design-Workspace > Spacing)
// Added to theme.space via extendTheme — Chakra's numeric defaults are preserved.
// Values are in rem so spacing scales with a user's root font-size / browser zoom
// (WCAG 1.4.4). Border widths (below) intentionally stay in px: hairline geometry
// shouldn't scale with zoom.

// prettier-ignore
export const spacing = {
  '3xs': '0.125rem', // 2px
  '2xs': '0.25rem',  // 4px
  xs:    '0.5rem',   // 8px
  s:     '0.75rem',  // 12px
  m:     '1rem',     // 16px
  l:     '1.25rem',  // 20px
  xl:    '1.5rem',   // 24px
  '2xl': '2rem',     // 32px
  '3xl': '2.5rem',   // 40px
  '4xl': '4rem',     // 64px
  '5xl': '5rem',     // 80px
  '6xl': '8rem',     // 128px
  '7xl': '10rem',    // 160px
} as const;

// Border widths — source of truth: Handover tokens/spacing.css (--zimm-border-width-default).
// Registered as theme.borderWidths; the CSS-var twin already exists in zimmTokens.ts.
export const borderWidths = {
  default: '1px',
} as const;

// Focus-ring outline offsets — hairline geometry, stays px like border widths above.
// `secondary` clears the 1px border on the secondary button variant (Handover
// button.md §focus) — the name describes that variant, not a generic scale step,
// since nothing else currently needs a third offset value.
export const focusRingOffsets = {
  default: '2px',
  secondary: '3px',
} as const;

// Icon sizes — source: Zimmermann Design System 2026 (Handover tokens.md § Icon Sizes)
//
// Deliberately NOT registered as `theme.sizes`. Chakra's `sizes.lg` is 32rem and
// backs every `w`/`h`/`boxSize` token across the base retail-react-app, so
// remapping these names would resize base components. Import these constants
// directly instead — the same pattern component overrides already use for
// FONT_MEDIUM: `<Icon boxSize={iconSizes.lg} />`.
export const iconSizes = {
  lg: '20px',
  md: '16px',
  sm: '12px',
} as const;

// Action (button) sizing — source: Handover tokens/spacing.css (--zimm-size-action-*).
// The CSS-var twins already exist in zimmTokens.ts. These are the Handover-correct
// values; button.ts (the single source of truth for actual button styling — no
// .zimm-btn-* class duplicates it) currently uses different prototype values for
// height (BTN_HEIGHT_LG/SM), flagged there pending UI-designer sign-off.
export const actionSizes = {
  height: {
    lg: '52px',
    md: '40px',
  },
  paddingX: {
    lg: '32px',
    md: '20px',
  },
  gap: '16px',
} as const;

