import React from 'react';
import { Global, css } from '@emotion/react';
import { zimmTokens } from './foundation/zimmTokens';

// Injects the --zimm-* custom properties onto :root via a raw Emotion <Global>.
//
// Deliberately NOT Chakra's styles.global: Chakra's style processor mangles quoted
// font-family values (verified — "'Futura Round', 'Century Gothic', sans-serif"
// collapses to a single family), which would break the --zimm-font-family-* vars.
// A raw Emotion <Global> preserves them.
//
// Rendered in the app by _app-config/index.tsx AND in Storybook by
// .storybook/preview.tsx, so the .zimm-* global classes and the var(--zimm-*)
// component overrides resolve identically in both. Kept as one shared definition
// so the two mount points cannot drift.
export const zimmRootVarsCss = css`
  :root {
    ${Object.entries(zimmTokens)
      .map(([k, v]) => `${k}:${v}`)
      .join(';')}
  }
`;

/** Injects the --zimm-* :root custom properties. Render once, high in the tree. */
export function ZimmTokensGlobal(): React.ReactElement {
  return <Global styles={zimmRootVarsCss} />;
}

import { FONT_MEDIUM, FONT_REGULAR, FONT_SERIF } from './fonts';

// Typography scale primitives — deduplicated from the 22 Handover text styles below.
// zimmTokens.ts's --zimm-font-size-*/lineheight-*/letterspacing-* entries read from
// here too. Naming matches those --zimm-* suffixes.
export const fontSizes = {
  md: '1.5rem', // 24px
  xs: '1rem', // 16px
  '2xs': '0.875rem', // 14px
  '3xs': '0.75rem', // 12px
  '4xs': '0.625rem', // 10px
} as const;

export const lineHeights = {
  md: '2rem', // 32px
  xs: '1.5rem', // 24px
  '2xs': '1.125rem', // 18px
  '3xs': '1rem', // 16px
  '4xs': '0.875rem', // 14px
} as const;

export const letterSpacings = {
  sm: '0',
  xs: '-0.0075rem', // -0.12px
  // Only used by linkLg — still a named token rather than a raw literal so it can't
  // drift out of sync with globalStyles.ts's zimmTextLinkLg.
  '2xs': '-0.00875rem', // -0.14px
  footer: '0.025rem', // 0.4px
} as const;

export const fontWeights = {
  medium: '500',
  regular: '400',
} as const;

// Named text styles — source: Zimmermann Design System 2026 (Handover tokens/typography.css)
// Token name → fontFamily / fontWeight / fontSize / lineHeight / letterSpacing / transform
export const textStyles = {
  // ---- Headings ----
  // ZIM/h1-strong (.zimm-text-h1-strong): 500 weight, uppercase
  heading1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h1 (.zimm-text-h1): 400 weight, uppercase
  heading1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h2-strong (.zimm-text-h2-strong)
  heading2: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/h3-strong (.zimm-text-h3-strong)
  heading3: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'uppercase' as const,
  },
  // ---- Body ----
  // ZIM/body1-strong (.zimm-text-body1-strong)
  body1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body1 (.zimm-text-body1)
  body1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2-strong (.zimm-text-body2-strong)
  body2Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2 (.zimm-text-body2)
  body2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Mobile body ----
  // ZIM/Mobile/Body1-strong (.zimm-text-mobile-body1-strong)
  mobileBody1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/Mobile/Body1 (.zimm-text-mobile-body1)
  mobileBody1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/Mobile/Body2 (.zimm-text-mobile-body2)
  mobileBody2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Utility ----
  // ZIM/Label (.zimm-text-label)
  label: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // Default/Caption (.zimm-text-caption)
  caption: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Links ----
  // ZIM/Link-lg (.zimm-text-link-lg): uppercase + underline
  linkLg: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings['2xs'],
    textTransform: 'uppercase' as const,
    textDecoration: 'underline',
  },
  // ZIM/Link-sm (.zimm-text-link-sm): capitalize + underline
  linkSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'capitalize' as const,
    textDecoration: 'underline',
  },
  // ---- Buttons ----
  // ZIM/Button-lg — no .zimm-text-btn-lg class; button.ts composes this textStyle
  // directly (single source of truth for button styling).
  button: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/Button-sm — no .zimm-text-btn-sm class, same reason as the button style above.
  buttonSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ---- Commerce ----
  // ZIM/Product-name (.zimm-text-product-name)
  productNames: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/Price (.zimm-text-price)
  price: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Navigation ----
  // ZIM/Navigation (.zimm-text-nav)
  navigation: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: 'normal',
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ---- Footer ----
  // ZIM/Footer (.zimm-text-footer)
  footer: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['4xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.footer,
    textTransform: 'uppercase' as const,
  },
  // ---- Serif accent (Source Serif 4, italic) ----
  // Default/Serif (.zimm-text-serif)
  serif: {
    fontFamily: FONT_SERIF,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.regular,
    fontStyle: 'italic' as const,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
  },
};

// Futura Round IS self-hosted — two faces (400, 500) ship from overrides/app/static/fonts/,
// declared by theme/fontFace.tsx. The stack below is the fallback chain, used only where the
// self-hosted face has not loaded. See frozenFiles.md > Design System.
// (Upstream source: Handover tokens/typography.css.)
// Fallbacks mirror the prototype's font stack so Century Gothic / Gill Sans renders
// on machines where Futura Round is unavailable — much closer to the brand look than Arial.
export const FONT_REGULAR =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";
export const FONT_MEDIUM =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";

// Source Serif 4 (400 italic) is the Handover's decorative serif accent, but no
// @font-face or .woff2 ships for it yet — this stack renders Georgia today.
// Self-host it (SIL OFL, free via Google Fonts) when a component first needs it.
export const FONT_SERIF = "'Source Serif 4', 'Georgia', serif";

export const fonts = {
  heading: FONT_MEDIUM,
  body: FONT_REGULAR,
  mono: FONT_REGULAR,
};

// Motion tokens — source: Zimmermann Design System 2026 (Handover common.css)
// PROVISIONAL: Motion design is pending formal sign-off. Values are functional
// placeholders used in prototypes. Do not treat as final — confirm with the UI
// designer against the Handover design system before relying on them.
export const motion = {
  duration: {
    fast: '200ms',
    default: '300ms',
    slow: '500ms',
  },
  easing: {
    // General-purpose default
    standard: 'ease',
    // Luxury deceleration — panels and overlays entering the screen (from common.css)
    slides: 'cubic-bezier(0.87, 0, 0.13, 1)',
    // Fades (from common.css)
    fades: 'cubic-bezier(0.37, 0, 0.63, 1)',
  },
} as const;

// Grid system — source of truth: Figma node 2081:53035 (Design-Workspace > Grid layouts)
//
//   Mobile   (base, < 768px):   4 columns, 30px container padding, 1px gutter
//   Tablet   (md,   768–1279px): 8 columns, 24px container padding, 1px gutter
//   Desktop  (xl,  ≥ 1280px):  10 columns,  0px container padding, 1px gutter

// prettier-ignore
export const breakpoints = {
  base: '0em',
  sm: '30em',       // NOT used (480px)
  md: '48em', // 768px — tablet breakpoint
  lg: '62em',       // NOT used (992px)
  xl: '80em', // 1280px — desktop breakpoint
  '2xl': '96em',    // NOT used (1536px)
} as const;

export const grid = {
  columns: { base: 4, md: 8, xl: 10 },
  containerPadding: { base: '30px', md: '24px', xl: '0' },
  columnGap: '1px',
} as const;

content.content:
**Standing constraints stated by the user (preserve verbatim):**
- *"the licence must be taken/kept out of the codebase"*
- *"remove anything that mentions jersey, and for #6 remove any mentions of the licence just state that the fonts are being self-hosted for development and testing"*
- "Do not call the AgentTool unless the user requested it"
- "Do not use workflows or deep-research unless the user requested it"
- Branch rules: never operate on `develop` or `main`
- Never run `npm start` (AGENTS.md — dev server is shared; ask the user)
- Commits/pushes/PRs only on explicit request (AGENTS.md Hard Rule #15)
- Four absolute Tier 1 files where the verified-session exception does NOT apply: `overrides/app/ssr.js`, `config/default.js`, `config/sites.js`, `worker/main.js`

## 2. Key Technical Concepts

- **Salesforce PWA Kit v10** with `ccExtensibility` overrides pattern; resolver is webpack-only (Storybook/Vitest don't load it)
- **Chakra UI v2.7.0** — `useMultiStyleConfig`, `useStyleConfig`, `__css`, `sx`, `textStyle`, `defineStyleConfig`, `toCSSVar`
- **The two-scale trap**: `width`/`height`/`boxSize`/`min|maxWidth|Height` resolve through **`theme.sizes`**; `margin`/`padding`/`gap`/`top`-`right`-`bottom`-`left` through **`theme.space`**. The Zimmermann scale is registered as `space` only (`theme/index.ts:56`), deliberately — so a bare key on a sizing prop reads Chakra's defaults (`sizes.xl` = 36rem = 576px)
- **Compound-value trap**: Chakra resolves a token only as the *entire* value. `padding: 'xs 0'` is emitted verbatim → browser drops the declaration
- **`extendTheme` deep-merges**: a recipe named `Footer` inherits SFCC's `Footer` rather than replacing it. Colliding part names inherit base properties; a new key you add is appended **last**, so a shorthand can reset a base longhand
- **Token derivation chain**: `foundation/*.ts` → `zimmTokens.ts` → `var(--zimm-*)` → recipes → components
- **`ZimmTokensGlobal` pattern** — raw Emotion `<Global>` (not Chakra `styles.global`, which mangles quoted font-family values), dual-mounted in `_app-config/index.tsx` and `.storybook/preview.tsx`
- **Tier system**: Tier 1 (`foundation/`, `.claude/rules/`, `.storybook/`, `.github/workflows/`), Tier 2 (`theme/components/`, `components/footer|header`, `_app-config/`)
- **Tier 1 verified-session exception** — `gh api user --jq .login` + team/admin check
- **WCAG**: 2.5.3 Label in Name (Level A), 2.4.7 Focus Visible, 2.5.8 Target Size
- **Playwright measurement methodology**: `waitUntil: 'domcontentloaded'` (networkidle never settles on a dev server); programmatic `.focus()` does NOT trigger `:focus-visible`; hydration race drops keystrokes if typing starts too early
- **Figma MCP**: `get_metadata`, `get_screenshot`, `get_variable_defs`

## 3. Files and Code Sections

### `overrides/app/theme/components/footer.ts` (heavily modified)
The footer's multipart recipe. Changes this session:

**Renamed export (fixes the extendTheme merge):**
```ts
export const ZimmFooter = {
  parts: [...33 parts...],
  baseStyle: { ... }
}
```

**`BP` block — imports the foundation breakpoint:**
```ts
import { breakpoints } from '../foundation/gridSystem';

const BP = {
  tablet: breakpoints.md,      // Figma: alias/breakpoint/tablet — 768px
  tabletWide: '53.75em',       // 860px (no foundation equivalent)
  desktop: '64em',             // 1024px (≠ Chakra lg=62em / xl=80em)
} as const;
```

**`contactIconLink` — the 576px bug fix:**
```ts
// MUST be the CSS var, not the bare token key 'xl': Chakra resolves width/height
// through theme.sizes, not theme.space, and Chakra's default sizes.xl is 36rem
// (576px) — which blew each icon up to 576px and destroyed the whole footer layout.
contactIconLink: {
  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
  width: 'var(--zimm-scale-xl)',
  height: 'var(--zimm-scale-xl)',
  color: 'var(--zimm-color-text-inverse)',
},
```

**`modalOverlay` z-index fix:**
```ts
// Chakra zIndices.overlay (1300). Must clear the sticky header, which sets
// zIndex: 'sticky' (1100) in header.ts. The portal target is document.body, so
// this competes in the root stacking context, not the footer's.
zIndex: 'overlay',
```

**`linkCol` — 160px cap:**
```ts
[`@media (min-width: ${BP.tablet})`]: {
  width: 'auto',
  maxWidth: 'var(--zimm-scale-7xl)', // 10rem (160px) — see the threshold note above
  flexShrink: 1,
},
```

**`copyright` / `legalLink` — compound shorthand fix:**
```ts
